const config = $('Config').first().json;
const out = [];
const supported = ['sem_google', 'social_meta', 'social_linkedin', 'social_generic'];

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
}

for (const item of $input.all()) {
  for (const candidate of item.json.data ?? []) {
    const tenant = candidate.tenant;
    if (!tenant || tenant.enabled === false) continue;
    if (!candidate.external_id) continue;

    const channel = candidate.channel || 'seo';
    if (!supported.includes(channel)) continue;

    const isSem = channel === 'sem_google';
    const kind = isSem ? 'sem_landing' : 'social_post';
    const platform = isSem ? 'google_ads' : channel.replace(/^social_/, '');
    const campaign = (tenant.slug + '-' + slugify(candidate.query)).slice(0, 100);

    out.push({
      json: {
        candidateId: candidate.id,
        candidateExternalId: candidate.external_id,
        tenantId: tenant.id,
        tenantSlug: tenant.slug,
        locale: tenant.locale || 'en',
        market: tenant.market || '',
        brandVoice: tenant.brand_voice || '',
        query: candidate.query,
        intent: candidate.intent || '',
        reason: candidate.reason || '',
        channel: channel,
        kind: kind,
        platform: platform,
        externalKey: tenant.slug + ':' + kind + ':' + candidate.external_id,
        utm: {
          utm_source: platform,
          utm_medium: isSem ? 'cpc' : 'social',
          utm_campaign: campaign,
        },
        siteBaseUrl: config.siteBaseUrl,
        directusUrl: config.directusUrl,
        aiEndpoint: config.aiEndpoint,
        aiModel: config.aiModel,
      },
    });
  }
}

return out;

const c = $('Loop Over Items').first().json;

const shared = [
  'You are a performance marketing copywriter for a client site.',
  'Locale: ' + c.locale + '. Market: ' + (c.market || 'unspecified') + '.',
  'Brand voice: ' + (c.brandVoice || 'clear, specific, no hype') + '.',
  'Target query or topic: ' + c.query,
  'Why it was approved: ' + c.reason,
  'Never invent prices, discounts, certifications, materials, or dimensions. Use TBD instead.',
  'Return JSON only. No markdown fences, no commentary.',
].join('\n');

let task;
if (c.platform === 'google_ads') {
  task = [
    'Write a Google Ads Responsive Search Ad asset set for this query.',
    'Return JSON with keys: ad_group (string, max 60 chars), headlines (8-15 strings, each max 30 chars), descriptions (3-4 strings, each max 90 chars), keywords (10-20 lowercase phrases), final_path (string starting with /), sitelinks (0-4 objects with text max 25 chars and path starting with /).',
    'No superlatives, no guarantees, no all caps, at most one exclamation mark across all headlines.',
  ].join('\n');
} else if (c.platform === 'meta') {
  task = [
    'Write one Meta (Facebook/Instagram) feed post.',
    'Return JSON with keys: caption (string, max 2200 chars, at most 3 emoji, one clear call to action), hashtags (5-10 strings without #), link_path (string starting with /), image_prompt (concrete photo brief for a real product or scene), scheduled_at (ISO 8601 string or empty).',
  ].join('\n');
} else if (c.platform === 'linkedin') {
  task = [
    'Write one LinkedIn company page post.',
    'Return JSON with keys: caption (string, max 3000 chars, professional and specific, no hashtag spam), hashtags (3-5 strings without #), link_path (string starting with /), image_prompt (concrete photo brief), scheduled_at (ISO 8601 string or empty).',
  ].join('\n');
} else {
  task = [
    'Write one cross-channel social post that will be delivered through a generic webhook.',
    'Return JSON with keys: caption (string, max 1200 chars), hashtags (3-8 strings without #), link_path (string starting with /), image_prompt (concrete photo brief), scheduled_at (ISO 8601 string or empty).',
  ].join('\n');
}

return [{
  json: Object.assign({}, c, {
    systemPrompt: shared + '\n' + task,
    userPrompt: 'Channel: ' + c.platform + '. Deliverable kind: ' + c.kind + '. UTM: ' + JSON.stringify(c.utm),
    startedAt: new Date().toISOString(),
  }),
}];

const raw = $json.choices?.[0]?.message?.content;
if (!raw) throw new Error('AI response missing choices[0].message.content');

const tick = String.fromCharCode(96);
const cleaned = String(raw)
  .split('\n')
  .filter(function (line) { return line.trim().indexOf(tick) !== 0; })
  .join('\n')
  .trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error('AI response is not valid JSON: ' + error.message);
}

const c = $('Build prompt').first().json;
const base = String(c.siteBaseUrl || '').replace(/\/+$/, '');

function fullUrl(path) {
  if (!path) return base;
  if (/^https?:\/\//.test(path)) return path;
  return base + (path.charAt(0) === '/' ? path : '/' + path);
}

function withUtm(url) {
  if (!url) return '';
  const query = Object.keys(c.utm)
    .map(function (key) { return key + '=' + encodeURIComponent(c.utm[key]); })
    .join('&');
  return url + (url.indexOf('?') === -1 ? '?' : '&') + query;
}

let payload;
let title;
let bodyMd;

if (c.platform === 'google_ads') {
  const headlines = Array.isArray(parsed.headlines) ? parsed.headlines.filter(Boolean).slice(0, 15) : [];
  const descriptions = Array.isArray(parsed.descriptions) ? parsed.descriptions.filter(Boolean).slice(0, 4) : [];
  if (!headlines.length || !descriptions.length) {
    throw new Error('Google Ads asset needs headlines and descriptions');
  }
  const keywords = Array.isArray(parsed.keywords) ? parsed.keywords.map(String) : [];
  const sitelinks = Array.isArray(parsed.sitelinks) ? parsed.sitelinks.slice(0, 4) : [];
  const finalUrl = withUtm(fullUrl(parsed.final_path));

  payload = {
    platform: 'google_ads',
    ad_group: parsed.ad_group || c.query,
    headlines: headlines,
    descriptions: descriptions,
    keywords: keywords,
    final_url: finalUrl,
    sitelinks: sitelinks,
    utm: c.utm,
  };
  title = payload.ad_group;
  bodyMd = [
    '## Headlines',
    headlines.map(function (item) { return '- ' + item; }).join('\n'),
    '',
    '## Descriptions',
    descriptions.map(function (item) { return '- ' + item; }).join('\n'),
    '',
    '## Keywords',
    keywords.join(', '),
    '',
    '## Final URL',
    finalUrl,
    '',
    '## Sitelinks',
    sitelinks.map(function (item) { return '- ' + (item.text || '') + ' -> ' + (item.path || ''); }).join('\n'),
  ].join('\n');
} else {
  if (!parsed.caption) throw new Error('Social asset needs caption');
  const hashtags = Array.isArray(parsed.hashtags)
    ? parsed.hashtags.map(function (tag) { return String(tag).replace(/^#/, ''); }).slice(0, 12)
    : [];
  const linkUrl = parsed.link_path ? withUtm(fullUrl(parsed.link_path)) : '';

  payload = {
    platform: c.platform,
    caption: String(parsed.caption),
    hashtags: hashtags,
    link_url: linkUrl,
    image_prompt: parsed.image_prompt || '',
    scheduled_at: parsed.scheduled_at ? String(parsed.scheduled_at) : '',
    utm: c.utm,
  };
  title = String(parsed.caption).slice(0, 80);
  bodyMd = [
    payload.caption,
    '',
    hashtags.map(function (tag) { return '#' + tag; }).join(' '),
    linkUrl ? '\n' + linkUrl : '',
  ].join('\n').trim();
}

return [{
  json: {
    deliverable: {
      tenant: c.tenantId,
      candidate: c.candidateId,
      external_key: c.externalKey,
      kind: c.kind,
      status: 'ready',
      title: title,
      body_md: bodyMd,
      seo_title: '',
      seo_description: '',
      keywords: c.platform === 'google_ads' ? payload.keywords : [],
      target_categories: [],
      target_tags: [],
      payload: payload,
      ai_model: c.aiModel,
      ai_run_id: $execution.id,
    },
  },
}];
